"""タイトル画面。make_title.py が生成する（手で編集しない）。

画像は16色に量子化した生インデックス列を zlib+base64 で持つ。
Image.data_ptr() へ一括で書き込むので展開は一瞬で終わる。
"""
import base64
import zlib

import pyxel

PALETTE = (
    0xFFF602,
    0x0044EA,
    0x920502,
    0xCDFAFF,
    0x5DBC64,
    0x00154C,
    0xEA7158,
    0x3DCDFF,
    0x237B04,
    0xE0E283,
    0x9DAA02,
    0x7C4C64,
    0x95ADC4,
    0x136F84,
    0xD63F0D,
    0x4D78E9,
)

_DATA = {
    (256, 256): '',
    (256, 192): '',
}
_CACHE = {}


def image(w, h):
    """その大きさのタイトル画像を返す。初回だけ展開する。"""
    key = (w, h)
    if key in _CACHE:
        return _CACHE[key]
    raw = _DATA.get(key) or _DATA[(256, 256)]
    img = pyxel.Image(w, h)
    img.data_ptr()[:] = zlib.decompress(base64.b64decode(raw))
    _CACHE[key] = img
    return img


def apply_palette():
    """タイトル専用の16色を当てる。"""
    for i, c in enumerate(PALETTE):
        pyxel.colors[i] = c


def draw(w, h):
    apply_palette()
    pyxel.blt(0, 0, image(w, h), 0, 0, w, h)
